import sys, json
import pandas as pd
import numpy as np

def rnd(x, nd=2):
    return round(float(x), nd)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---------- TOTALS ----------
    tot_rev_tw = df['Revenue_TW'].sum(skipna=True)
    tot_rev_lw = df['Revenue_LW'].sum(skipna=True)
    tot_rev_ly = df['Revenue_LY'].sum(skipna=True) if df['Revenue_LY'].notna().any() else None
    tot_units_tw = df['Units_TW'].sum(skipna=True)
    tot_units_lw = df['Units_LW'].sum(skipna=True)
    tot_orders_tw = df['Orders_TW'].sum(skipna=True)
    tot_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": rnd(tot_rev_tw), "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": rnd(tot_rev_lw), "formula": "sum(Revenue_LW)"
    })
    if tot_rev_ly is not None:
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": rnd(tot_rev_ly), "formula": "sum(Revenue_LY)"
        })

    if tot_rev_lw and not np.isnan(tot_rev_lw) and tot_rev_lw != 0:
        wow = (tot_rev_tw - tot_rev_lw) / tot_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": rnd(wow, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if tot_rev_ly is not None and tot_rev_ly != 0:
        yoy = (tot_rev_tw - tot_rev_ly) / tot_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": rnd(yoy, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": rnd(tot_units_tw, 2), "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": rnd(tot_units_lw, 2), "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": rnd(tot_orders_tw, 2), "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": rnd(tot_orders_lw, 2), "formula": "sum(Orders_LW)"
    })

    # ---------- TOP ENTITIES BY REVENUE_TW ----------
    top_df = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(5)
    for _, row in top_df.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": rnd(row['Revenue_TW']), "formula": "Revenue_TW"
        })
        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": row['Entity'], "metric": "share", "period": "TW",
                "value": rnd(row['Share_Pct'], 1), "formula": "Share_Pct"
            })

    # ---------- BIGGEST WoW MOVERS ----------
    wow_valid = df.dropna(subset=['WoW_Pct'])
    if not wow_valid.empty:
        max_row = wow_valid.loc[wow_valid['WoW_Pct'].idxmax()]
        min_row = wow_valid.loc[wow_valid['WoW_Pct'].idxmin()]
        facts.append({
            "entity": max_row['Entity'], "metric": "revenue", "period": "WoW",
            "value": rnd(max_row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })
        if min_row['Entity'] != max_row['Entity']:
            facts.append({
                "entity": min_row['Entity'], "metric": "revenue", "period": "WoW",
                "value": rnd(min_row['WoW_Pct'], 1),
                "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
            })

    # ---------- BIGGEST YoY MOVERS ----------
    yoy_valid = df.dropna(subset=['YoY_Pct'])
    if not yoy_valid.empty:
        max_row = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmax()]
        min_row = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmin()]
        facts.append({
            "entity": max_row['Entity'], "metric": "revenue", "period": "YoY",
            "value": rnd(max_row['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })
        if min_row['Entity'] != max_row['Entity']:
            facts.append({
                "entity": min_row['Entity'], "metric": "revenue", "period": "YoY",
                "value": rnd(min_row['YoY_Pct'], 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

    # ---------- RANK 1 ENTITY DETAILS ----------
    if 'Rank' in df.columns and df['Rank'].notna().any():
        rank1 = df.loc[df['Rank'].idxmin()]
        facts.append({
            "entity": rank1['Entity'], "metric": "rank", "period": "TW",
            "value": rnd(rank1['Rank'], 0), "formula": "Rank"
        })

    # limit to 25 facts
    facts = facts[:25]

    # convert any numpy types
    clean_facts = []
    for f in facts:
        v = f['value']
        if isinstance(v, (np.floating, np.integer)):
            v = float(v)
        f['value'] = v
        clean_facts.append(f)

    print(json.dumps(clean_facts))

if __name__ == "__main__":
    main()
